from datetime import date; from decimal import Decimal; from uuid import UUID, uuid4; import pytest; from fastapi import status; from httpx import AsyncClient; from sqlalchemy import select; from sqlalchemy.ext.asyncio import AsyncSession; from src.identity import User; from src.ledger import Account, AccountType, JournalEntry, JournalEntryStatus, JournalLine; pytestmark = pytest.mark.asyncio
@pytest.fixture
async def test_accounts(db: AsyncSession, test_user: User):
    accounts = []; cash_account = Account(id=uuid4(), user_id=test_user.id, name='Cash', type=AccountType.ASSET, currency='SGD'); db.add(cash_account); accounts.append(cash_account); income_account = Account(id=uuid4(), user_id=test_user.id, name='Service Income', type=AccountType.INCOME, currency='SGD'); db.add(income_account); accounts.append(income_account); await db.commit()
    for acc in accounts: await db.refresh(acc)
    return accounts
@pytest.fixture
async def test_entries(db: AsyncSession, test_user: User, test_accounts: list[Account]):
    entries = []; draft_entry = JournalEntry(id=uuid4(), user_id=test_user.id, entry_date=date(2023, 1, 15), memo='Test draft entry', status=JournalEntryStatus.DRAFT); db.add(draft_entry); await db.flush(); draft_line_debit = JournalLine(id=uuid4(), journal_entry_id=draft_entry.id, account_id=test_accounts[0].id, direction='DEBIT', amount=Decimal('100.00'), currency='SGD'); draft_line_credit = JournalLine(id=uuid4(), journal_entry_id=draft_entry.id, account_id=test_accounts[1].id, direction='CREDIT', amount=Decimal('100.00'), currency='SGD'); db.add(draft_line_debit); db.add(draft_line_credit); entries.append(draft_entry); posted_entry = JournalEntry(id=uuid4(), user_id=test_user.id, entry_date=date(2023, 1, 16), memo='Test posted entry', status=JournalEntryStatus.POSTED); db.add(posted_entry); await db.flush(); posted_line_debit = JournalLine(id=uuid4(), journal_entry_id=posted_entry.id, account_id=test_accounts[0].id, direction='DEBIT', amount=Decimal('200.00'), currency='SGD'); posted_line_credit = JournalLine(id=uuid4(), journal_entry_id=posted_entry.id, account_id=test_accounts[1].id, direction='CREDIT', amount=Decimal('200.00'), currency='SGD'); db.add(posted_line_debit); db.add(posted_line_credit); entries.append(posted_entry); await db.commit()
    for entry in entries: await db.refresh(entry, ['lines'])
    return entries
async def test_create_journal_entry(client: AsyncClient, db: AsyncSession, test_user: User, test_accounts: list[Account]): 'AC-ledger.7.1'; entry_data = {'entry_date': '2023-01-15', 'memo': 'Test entry', 'lines': [{'account_id': str(test_accounts[0].id), 'direction': 'DEBIT', 'amount': '100.00', 'currency': 'SGD'}, {'account_id': str(test_accounts[1].id), 'direction': 'CREDIT', 'amount': '100.00', 'currency': 'SGD'}]}; response = await client.post('/journal-entries', json=entry_data); assert response.status_code == status.HTTP_201_CREATED; data = response.json(); assert data['id'] is not None; assert data['entry_date'] == '2023-01-15'; assert data['memo'] == 'Test entry'; assert data['status'] == 'draft'; assert len(data['lines']) == 2; result = await db.execute(select(JournalEntry).where(JournalEntry.id == UUID(data['id']))); entry = result.scalar_one(); assert entry is not None; assert entry.user_id == test_user.id; assert entry.entry_date == date(2023, 1, 15); assert entry.memo == 'Test entry'
async def test_create_unbalanced_entry(client: AsyncClient, db: AsyncSession, test_user: User, test_accounts: list[Account]): 'AC-ledger.7.2'; invalid_data = {'entry_date': '2023-01-15', 'memo': 'Invalid entry', 'lines': [{'account_id': str(test_accounts[0].id), 'direction': 'DEBIT', 'amount': '100.00'}, {'account_id': str(test_accounts[1].id), 'direction': 'CREDIT', 'amount': '99.00'}]}; response = await client.post('/journal-entries', json=invalid_data); assert response.status_code == status.HTTP_400_BAD_REQUEST; assert 'not balanced' in response.json()['detail'].lower()
async def test_effective_usd_base_defaults_line_currency_at_ledger_boundary(client: AsyncClient, db: AsyncSession, test_user: User) -> None: accounts = [Account(user_id=test_user.id, name='USD Cash', type=AccountType.ASSET, currency='USD'), Account(user_id=test_user.id, name='USD Income', type=AccountType.INCOME, currency='USD')]; db.add_all(accounts); await db.flush(); account_ids = [account.id for account in accounts]; await db.commit(); update = await client.put('/app-config/base-currency', json={'base_currency': 'USD'}); assert update.status_code == 200, update.text; response = await client.post('/journal-entries', json={'entry_date': '2026-01-15', 'memo': 'USD base entry', 'lines': [{'account_id': str(account_ids[0]), 'direction': 'DEBIT', 'amount': '100.00'}, {'account_id': str(account_ids[1]), 'direction': 'CREDIT', 'amount': '100.00'}]}); assert response.status_code == status.HTTP_201_CREATED, response.text; assert {line['currency'] for line in response.json()['lines']} == {'USD'}
async def test_list_journal_entries(client: AsyncClient, db: AsyncSession, test_user: User, test_entries: list[JournalEntry]): 'AC-ledger.7.3'; response = await client.get('/journal-entries'); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert data['total'] >= len(test_entries); assert len(data['items']) > 0; response = await client.get('/journal-entries?status_filter=draft'); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert data['total'] >= 1; assert all((item['status'] == 'draft' for item in data['items'])); start_date = date(2023, 1, 1); end_date = date(2023, 12, 31); response = await client.get(f'/journal-entries?start_date={start_date}&end_date={end_date}'); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert data['total'] >= 1; response = await client.get('/journal-entries?limit=1&offset=0'); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert len(data['items']) <= 1
async def test_get_journal_entry(client: AsyncClient, db: AsyncSession, test_user: User, test_entries: list[JournalEntry]): 'AC-ledger.7.4'; entry = test_entries[0]; response = await client.get(f'/journal-entries/{entry.id}'); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert data['id'] == str(entry.id); assert data['memo'] == entry.memo; non_existent_id = uuid4(); response = await client.get(f'/journal-entries/{non_existent_id}'); assert response.status_code == status.HTTP_404_NOT_FOUND
async def test_post_journal_entry(client: AsyncClient, db: AsyncSession, test_user: User, test_entries: list[JournalEntry]): 'AC-ledger.7.5'; draft_entry = next((e for e in test_entries if e.status == JournalEntryStatus.DRAFT), None); assert draft_entry is not None, 'No draft entry found'; legacy_response = await client.post(f'/journal-entries/{draft_entry.id}/postings'); assert legacy_response.status_code == status.HTTP_400_BAD_REQUEST; assert 'legacy-unproven' in legacy_response.json()['detail']; create_response = await client.post('/journal-entries', json={'entry_date': draft_entry.entry_date.isoformat(), 'memo': f'Anchored replacement for {draft_entry.memo}', 'rationale': 'Operator attested this exact draft before posting.', 'lines': [{'account_id': str(line.account_id), 'direction': getattr(line.direction, 'value', line.direction), 'amount': str(line.amount), 'currency': line.currency, 'fx_rate': str(line.fx_rate) if line.fx_rate is not None else None} for line in draft_entry.lines]}); assert create_response.status_code == status.HTTP_201_CREATED; anchored_entry_id = create_response.json()['id']; response = await client.post(f'/journal-entries/{anchored_entry_id}/postings'); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert data['status'] == 'posted'; await db.refresh(draft_entry); assert draft_entry.status == JournalEntryStatus.DRAFT; response = await client.post(f'/journal-entries/{anchored_entry_id}/postings'); assert response.status_code == status.HTTP_400_BAD_REQUEST; assert 'draft' in response.json()['detail'].lower(); non_existent_id = uuid4(); response = await client.post(f'/journal-entries/{non_existent_id}/postings'); assert response.status_code == status.HTTP_404_NOT_FOUND
async def test_void_journal_entry(client: AsyncClient, db: AsyncSession, test_user: User, test_entries: list[JournalEntry]): 'AC-ledger.7.6'; posted_entry = next((e for e in test_entries if e.status == JournalEntryStatus.POSTED), None); assert posted_entry is not None, 'No posted entry found'; void_request = {'reason': 'Test void reason'}; response = await client.post(f'/journal-entries/{posted_entry.id}/voidings', json=void_request); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert data['status'] == 'posted'; assert 'VOID:' in data['memo']; await db.refresh(posted_entry); assert posted_entry.status == JournalEntryStatus.VOID; assert posted_entry.void_reason == 'Test void reason'; assert posted_entry.void_reversal_entry_id is not None; draft_entry = next((e for e in test_entries if e.status == JournalEntryStatus.DRAFT), None); assert draft_entry is not None, 'test_entries fixture must contain a draft entry'; response = await client.post(f'/journal-entries/{draft_entry.id}/voidings', json=void_request); assert response.status_code == status.HTTP_400_BAD_REQUEST; assert 'posted' in response.json()['detail'].lower(); non_existent_id = uuid4(); response = await client.post(f'/journal-entries/{non_existent_id}/voidings', json=void_request); assert response.status_code == status.HTTP_400_BAD_REQUEST
async def test_delete_journal_entry(client: AsyncClient, db: AsyncSession, test_user: User, test_accounts: list[Account]): 'AC-ledger.7.7'; draft_entry = JournalEntry(id=uuid4(), user_id=test_user.id, entry_date=date(2023, 1, 20), memo='Entry to delete', status=JournalEntryStatus.DRAFT); db.add(draft_entry); await db.flush(); line_debit = JournalLine(id=uuid4(), journal_entry_id=draft_entry.id, account_id=test_accounts[0].id, direction='DEBIT', amount=Decimal('50.00'), currency='SGD'); line_credit = JournalLine(id=uuid4(), journal_entry_id=draft_entry.id, account_id=test_accounts[1].id, direction='CREDIT', amount=Decimal('50.00'), currency='SGD'); db.add(line_debit); db.add(line_credit); await db.commit(); draft_id = draft_entry.id; response = await client.delete(f'/journal-entries/{draft_id}'); assert response.status_code == status.HTTP_204_NO_CONTENT; result = await db.execute(select(JournalEntry).where(JournalEntry.id == draft_id)); entry = result.scalar_one_or_none(); assert entry is None; response = await client.delete(f'/journal-entries/{draft_id}'); assert response.status_code == status.HTTP_404_NOT_FOUND; non_existent_id = uuid4(); response = await client.delete(f'/journal-entries/{non_existent_id}'); assert response.status_code == status.HTTP_404_NOT_FOUND
